// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Vault {
    address public owner;
    uint256 public fee;

    function transferOwnership(address newOwner) external {
        require(msg.sender == owner, "not owner");
        owner = newOwner;
    }

    function setFee(uint256 newFee) external {
        require(msg.sender == owner, "not owner");
        fee = newFee;
    }
}
